"""Reproducible CLAP zero-shot versus observed-AKG prompt augmentation."""

import argparse
import csv
import json
import os
import sqlite3
import time
from functools import lru_cache
from unittest.mock import patch
from pathlib import Path

import numpy as np

from graph import DB, ROOT


META = ROOT / "data" / "ESC-50" / "meta" / "esc50.csv"
AUDIO = ROOT / "data" / "ESC-50" / "audio"
CACHE = ROOT / "data" / "cache"
RELATIONS = (
    "produces", "is sound of", "emitted by", "generated by", "transcribed as",
    "has timbre", "has pitch", "event composed of", "associated with event", "occurs in",
)


def unit(array):
    array = np.asarray(array, dtype=np.float32)
    return array / np.maximum(np.linalg.norm(array, axis=-1, keepdims=True), 1e-12)


def rank(scores, truth):
    order = np.argsort(-np.asarray(scores), kind="stable")
    return int(np.flatnonzero(order == truth)[0]) + 1


def metrics(ranks):
    a = np.asarray(ranks)
    return {"n": len(a), "hit1": float(np.mean(a <= 1)), "hit3": float(np.mean(a <= 3)),
            "hit5": float(np.mean(a <= 5)), "mrr": float(np.mean(1 / a))}


def metadata():
    if not META.exists():
        raise FileNotFoundError(f"ESC-50 metadata missing: {META}")
    with META.open(encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def context(label):
    # shortcut: exact normalized label and one observed fact; add audited aliases and multi-fact selection when coverage matters.
    name = label.replace("_", " ")
    placeholders = ",".join("?" for _ in RELATIONS)
    with sqlite3.connect(DB) as db:
        db.row_factory = sqlite3.Row
        row = db.execute(f"""SELECT head, relation, tail, source_file, source_row
                             FROM triple WHERE split='train' AND lower(head)=lower(?)
                             AND relation IN ({placeholders})
                             ORDER BY CASE relation """ + " ".join(
                                 f"WHEN '{relation}' THEN {i}" for i, relation in enumerate(RELATIONS)
                             ) + " END, tail LIMIT 1", (name, *RELATIONS)).fetchone()
    return dict(row) if row else None


class CLAP:
    def __init__(self):
        # Keep all model downloads inside this project.
        os.environ.setdefault("XDG_CACHE_HOME", str(CACHE.resolve()))
        os.environ.setdefault("TORCH_HOME", str((CACHE / "torch").resolve()))
        os.environ.setdefault("HF_HOME", str((CACHE / "huggingface").resolve()))
        (CACHE / "numba").mkdir(parents=True, exist_ok=True)
        os.environ.setdefault("NUMBA_CACHE_DIR", str((CACHE / "numba").resolve()))
        for key in ("HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY"):
            if os.environ.get(key, "").endswith(":9"):
                os.environ.pop(key)
        print("Loading LAION-CLAP package...", flush=True)
        import laion_clap
        import torch
        self.torch = torch
        from transformers import RobertaConfig, RobertaModel
        torch.set_num_threads(4)
        torch.set_num_interop_threads(2)
        print("Creating CLAP encoders...", flush=True)
        # The full CLAP checkpoint replaces all RoBERTa weights; skip a redundant 500 MB download.
        config = RobertaConfig(max_position_embeddings=514, type_vocab_size=1)
        with patch.object(RobertaModel, "from_pretrained", return_value=RobertaModel(config)):
            self.model = laion_clap.CLAP_Module(enable_fusion=False, device="cpu")
        checkpoint = ROOT / "data" / "630k-audioset-best.pt"
        if not checkpoint.exists():
            raise FileNotFoundError(f"Download the official LAION checkpoint first: {checkpoint}")
        print("Loading CLAP checkpoint...", flush=True)
        self.model.load_ckpt(ckpt=str(checkpoint), verbose=False)

    def text(self, prompts):
        with self.torch.inference_mode():
            return unit(self.model.get_text_embedding(prompts, use_tensor=False))

    def audio(self, path):
        with self.torch.inference_mode():
            return unit(self.model.get_audio_embedding_from_filelist(x=[str(path)], use_tensor=False))[0]


@lru_cache(maxsize=1)
def get_model():
    return CLAP()


def prompts(labels):
    triples = [context(label) for label in labels]
    base = [f"The sound of {label.replace('_', ' ')}." for label in labels]
    extra = [f"The sound of {label.replace('_', ' ')}. {triple['head']} {triple['relation']} {triple['tail']}."
             for label, triple in zip(labels, triples) if triple]
    return base, extra, triples


def text_vectors(model, labels):
    CACHE.mkdir(parents=True, exist_ok=True)
    target = CACHE / "text_vectors.npz"
    base, extra, triples = prompts(labels)
    signature = json.dumps({"base": base, "extra": extra}, sort_keys=True)
    if target.exists():
        cached = np.load(target)
        if str(cached["signature"]) == signature:
            return cached["base"], cached["augmented"], triples
    base_vectors = model.text(base)
    extra_vectors = model.text(extra) if extra else np.empty((0, base_vectors.shape[1]))
    augmented = base_vectors.copy()
    j = 0
    for i, triple in enumerate(triples):
        if triple:
            augmented[i] = unit(0.75 * base_vectors[i] + 0.25 * extra_vectors[j])
            j += 1
    np.savez(target, signature=signature, base=base_vectors, augmented=augmented)
    return base_vectors, augmented, triples


def audio_vector(model, path):
    CACHE.mkdir(parents=True, exist_ok=True)
    cache = CACHE / f"{path.stem}.npy"
    if cache.exists():
        return np.load(cache)
    value = model.audio(path)
    np.save(cache, value)
    return value


def evaluate(per_class):
    rows = metadata()
    labels = sorted({row["category"] for row in rows})
    selected = []
    for label in labels:
        examples = sorted((row for row in rows if row["category"] == label), key=lambda row: row["filename"])
        if per_class:
            by_fold = {fold: [row for row in examples if int(row["fold"]) == fold] for fold in range(1, 6)}
            examples = [by_fold[fold][index] for index in range(8) for fold in range(1, 6)]
        selected.extend(examples[:per_class] if per_class else examples)
    selected.sort(key=lambda row: (int(row["fold"]), row["category"], row["filename"]))
    model = get_model()
    baseline, enhanced, triples = text_vectors(model, labels)
    results = []
    started = time.time()
    for i, row in enumerate(selected, 1):
        path = AUDIO / row["filename"]
        if not path.is_file():
            raise FileNotFoundError(path)
        vector = audio_vector(model, path)
        b, k = vector @ baseline.T, vector @ enhanced.T
        true = labels.index(row["category"])
        results.append({"filename": row["filename"], "fold": int(row["fold"]), "truth": row["category"],
                        "baseline": labels[int(np.argmax(b))], "kg": labels[int(np.argmax(k))],
                        "baseline_rank": rank(b, true), "kg_rank": rank(k, true),
                        "baseline_score": float(np.max(b)), "kg_score": float(np.max(k))})
        if i % 10 == 0:
            print(f"Evaluated {i}/{len(selected)} clips in {time.time()-started:.1f}s", flush=True)
    output = ROOT / "results"
    output.mkdir(exist_ok=True)
    suffix = f"{per_class}perclass" if per_class else "full"
    with (output / f"predictions_{suffix}.csv").open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=results[0].keys())
        writer.writeheader()
        writer.writerows(results)
    summary = {"dataset": "ESC-50", "sample_rule": f"{per_class} per class, round-robin across folds by filename" if per_class else "all clips",
               "model": "LAION-CLAP non-fusion CPU", "classes": len(labels), "kg_covered_classes": sum(bool(x) for x in triples),
               "seconds": time.time() - started,
               "baseline": metrics([row["baseline_rank"] for row in results]),
               "kg": metrics([row["kg_rank"] for row in results]),
               "folds": {str(fold): {key: metrics([row[f"{key}_rank"] for row in results if row["fold"] == fold])
                                     for key in ("baseline", "kg")} for fold in sorted({row["fold"] for row in results})}}
    (output / f"summary_{suffix}.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")
    print(json.dumps(summary, indent=2), flush=True)


def predict(path):
    path = Path(path).resolve()
    if not path.is_file() or path.suffix.lower() not in {".wav", ".flac", ".mp3", ".ogg"}:
        raise ValueError("Provide an existing WAV/FLAC/MP3/OGG file")
    labels = sorted({row["category"] for row in metadata()})
    model = get_model()
    baseline, enhanced, triples = text_vectors(model, labels)
    vector = model.audio(path)
    scores = vector @ enhanced.T
    top = np.argsort(-scores)[:5]
    return {"audio": str(path), "baseline": labels[int(np.argmax(vector @ baseline.T))],
            "kg": [{"label": labels[int(i)], "score": float(scores[i]), "triple": triples[int(i)]} for i in top]}


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=("evaluate", "predict"))
    parser.add_argument("path", nargs="?")
    parser.add_argument("--per-class", type=int, default=1)
    args = parser.parse_args()
    if args.command == "evaluate":
        if args.per_class < 0 or args.per_class > 40:
            parser.error("--per-class must be between 0 (all) and 40")
        evaluate(args.per_class)
    elif not args.path:
        parser.error("predict requires an audio path")
    else:
        print(json.dumps(predict(args.path), indent=2))
